SELECT cpim.id, cpim.park_org_id, cpim.goods_id, cpim.MONTH, cpim.last_balance, cpim.last_balance_total, cpim.current_balance, cpim.current_balance_total, cpim.current_stock_in_number, cpim.current_stock_out_number, cpim.inventory_time, goods_type, goods_no, unit, goods_name, cpim.remark FROM cus_pro_inventory_manager cpim LEFT JOIN cus_pro_goods_manager cpgm ON cpim.goods_id = cpgm.id WHERE cpim.deleted = 0 AND cpgm.deleted = 0
and cpim.park_org_id = #{query.parkOrgId}
and cpim.park_org_id in
#{item}
and goods_name LIKE "%"#{query.goodsName}"%"
and cpim.MONTH = #{query.month}
ORDER BY cpim.create_time DESC
